import CryptoKit
import CZlib
import Foundation
import Testing
@testable import TryFydeOSCore

/// The VMDK fixtures shared with the Windows port, regenerated by their gen.sh.
func vmdkFixture(_ name: String) -> URL {
    URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        .appendingPathComponent("../../../windows/internal/vmdk/testdata/\(name)").standardizedFileURL
}

let fixtureBytes = 16 << 20

func goldenRawSha256() throws -> String {
    try String(contentsOf: vmdkFixture("raw.sha256"), encoding: .utf8).trimmingCharacters(in: .whitespacesAndNewlines)
}

func hex(_ digest: SHA256.Digest) -> String { digest.map { String(format: "%02x", $0) }.joined() }

func dataReader(_ data: Data) -> (UnsafeMutableRawBufferPointer) throws -> Int {
    var offset = 0
    return { buffer in
        let n = min(buffer.count, data.count - offset)
        data.copyBytes(to: buffer.bindMemory(to: UInt8.self), from: offset..<offset + n)
        offset += n
        return n
    }
}

/// Decodes into a fixture-sized raw buffer and returns its sha256.
func decodeToRaw(_ decode: ((Int64, UnsafeRawBufferPointer) throws -> Void) throws -> VMDKInfo) throws -> (VMDKInfo, String) {
    var raw = [UInt8](repeating: 0, count: fixtureBytes)
    let info = try decode { off, data in
        #expect(off >= 0 && Int(off) + data.count <= raw.count)
        raw.withUnsafeMutableBytes { UnsafeMutableRawBufferPointer(rebasing: $0[Int(off)..<Int(off) + data.count]).copyMemory(from: data) }
    }
    #expect(info.capacity == Int64(fixtureBytes) && info.grainBytes == 64 << 10)
    return (info, hex(SHA256.hash(data: raw)))
}

func decodeError(_ data: Data) -> String? {
    do {
        try VMDK.decode(read: dataReader(data)) { _, _ in }
        return nil
    } catch {
        return "\(error)"
    }
}

/// `sparse.vmdk.gz` inflated by /usr/bin/gunzip.
func sparseFixture() throws -> Data {
    let p = Process()
    p.executableURL = URL(fileURLWithPath: "/usr/bin/gunzip")
    p.arguments = ["-c", vmdkFixture("sparse.vmdk.gz").path]
    let out = Pipe()
    p.standardOutput = out
    try p.run()
    let data = out.fileHandleForReading.readDataToEndOfFile()
    p.waitUntilExit()
    #expect(p.terminationStatus == 0)
    return data
}

@Test func decodeStreamOptimized() throws {
    let data = try Data(contentsOf: vmdkFixture("stream.vmdk"))
    let (info, sum) = try decodeToRaw { try VMDK.decode(read: dataReader(data), write: $0) }
    #expect(sum == (try goldenRawSha256()))
    #expect(info.compressed && info.createType == "streamOptimized")
}

@Test func decodeMonolithicSparseFromAPipe() throws {
    let p = Process()
    p.executableURL = URL(fileURLWithPath: "/usr/bin/gunzip")
    p.arguments = ["-c", vmdkFixture("sparse.vmdk.gz").path]
    let out = Pipe()
    p.standardOutput = out
    try p.run()
    let (info, sum) = try decodeToRaw { try VMDK.decode(read: VMDK.reader(fd: out.fileHandleForReading.fileDescriptor), write: $0) }
    _ = out.fileHandleForReading.readDataToEndOfFile()
    p.waitUntilExit()
    #expect(sum == (try goldenRawSha256()))
    #expect(!info.compressed && info.createType == "monolithicSparse")
}

@Test func containersThroughTar() throws {
    for (name, disk) in [("test.ova", "stream.vmdk"), ("test.zip", "dir.vmwarevm/sparse.vmdk")] {
        let path = vmdkFixture(name)
        #expect(try VMDKContainer.findDisk(path) == disk)
        let members = try VMDKContainer.members(path)
        #expect(members.contains { $0.name == disk && $0.size > 0 })
        #expect(!members.contains { $0.name.hasSuffix("/") })
        var last: (Int64, Int64) = (0, 0)
        let (_, sum) = try decodeToRaw { try VMDKContainer.decodeDisk(path, progress: { last = ($0, $1) }, write: $0) }
        #expect(sum == (try goldenRawSha256()), "\(name)")
        #expect(last.1 == members.first { $0.name == disk }?.size && last.0 > 0)
    }
}

@Test func containerErrors() throws {
    for name in ["test.ova", "test.zip"] {
        #expect(throws: VMDKError.self) { try VMDKContainer.open(vmdkFixture(name), member: "nope.vmdk") }
    }
    #expect(throws: VMDKError.self) { try VMDKContainer.members(vmdkFixture("stream.vmdk")) }
    let root = try tempDir()
    defer { try? FileManager.default.removeItem(at: root) }
    let corrupt = root.appendingPathComponent("corrupt.zip")
    var zip = try Data(contentsOf: vmdkFixture("test.zip"))
    let name = Data("dir.vmwarevm/sparse.vmdk".utf8)
    let at = zip.range(of: name)!.upperBound + 100
    zip[at] ^= 0xff
    try zip.write(to: corrupt)
    #expect(throws: (any Error).self) { try VMDKContainer.decodeDisk(corrupt) { _, _ in } }
}

@Test func badMagic() throws {
    var data = try Data(contentsOf: vmdkFixture("stream.vmdk"))
    data[0] ^= 0xff
    #expect(decodeError(data)?.contains("magic") == true)
}

@Test func unsupportedFlags() throws {
    var data = try Data(contentsOf: vmdkFixture("stream.vmdk"))
    data.replaceSubrange(8..<12, with: [0, 0, 1, 0])
    #expect(decodeError(data)?.contains("flags 0x10000") == true)
}

@Test func truncated() throws {
    let stream = try Data(contentsOf: vmdkFixture("stream.vmdk"))
    for n in [100, 600, 128 * 512 + 100, 132 * 512] {
        #expect(decodeError(stream.prefix(n)) != nil, "stream cut at \(n) decoded")
    }
    let sparse = try sparseFixture()
    for n in [1000, 128 * 512, sparse.count - 100] {
        #expect(decodeError(sparse.prefix(n)) != nil, "sparse cut at \(n) decoded")
    }
}

func craftStream(lba: UInt64, payload: [UInt8]) -> Data {
    func le<T: FixedWidthInteger>(_ v: T) -> [UInt8] { withUnsafeBytes(of: v.littleEndian, Array.init) }
    var h = [UInt8](repeating: 0, count: 512)
    func put(_ at: Int, _ bytes: [UInt8]) { h.replaceSubrange(at..<at + bytes.count, with: bytes) }
    put(0, le(VMDK.magic))
    put(4, le(UInt32(3)))
    put(8, le(VMDK.flagCompressed | VMDK.flagMarkers))
    put(12, le(UInt64(256)))
    put(20, le(UInt64(128)))
    put(44, le(UInt32(512)))
    put(64, le(UInt64(1)))
    var z = [UInt8](repeating: 0, count: Int(compressBound(uLong(payload.count))))
    var zlen = uLong(z.count)
    #expect(compress2(&z, &zlen, payload, uLong(payload.count), 9) == Z_OK)
    var marker = [UInt8](repeating: 0, count: (12 + Int(zlen) + 511) / 512 * 512)
    marker.replaceSubrange(0..<8, with: le(lba))
    marker.replaceSubrange(8..<12, with: le(UInt32(zlen)))
    marker.replaceSubrange(12..<12 + Int(zlen), with: z[..<Int(zlen)])
    return Data(h + marker + [UInt8](repeating: 0, count: 512))
}

@Test func streamGrainChecks() {
    let grain = [UInt8](repeating: 7, count: 64 << 10)
    #expect(decodeError(craftStream(lba: 128, payload: grain)) == nil)
    #expect(decodeError(craftStream(lba: 256, payload: grain))?.contains("beyond capacity") == true)
    #expect(decodeError(craftStream(lba: 200, payload: grain)) != nil, "grain straddling capacity decoded")
    #expect(decodeError(craftStream(lba: 0, payload: grain + [1]))?.contains("inflates beyond") == true)
    #expect(decodeError(craftStream(lba: 0, payload: Array(grain[..<1000])))?.contains("inflates to 1000 bytes") == true)
    let full = craftStream(lba: 0, payload: grain)
    #expect(decodeError(full.prefix(full.count - 512)) != nil, "stream without end-of-stream marker decoded")
    var badAdler = full
    let zlen = Int(badAdler[512 + 8]) | Int(badAdler[512 + 9]) << 8
    badAdler[512 + 12 + zlen - 1] ^= 0xff
    #expect(decodeError(badAdler)?.contains("zlib") == true)
}
